"""Shared last-used-folder persistence for file dialogs."""

import os

from .appdirs import user_data_dir


def _path():
    try:
        return os.path.join(user_data_dir('MudLab'), 'last_folder.txt')
    except Exception:
        return None


def get_recent_folder():
    """Return the folder used in the last open/save, or None if not recorded or stale."""
    path = _path()
    if path is None:
        return None
    try:
        with open(path, 'r', encoding='utf-8') as f:
            folder = f.read().strip()
    except (OSError, IOError):
        return None
    return folder if folder and os.path.isdir(folder) else None


def set_recent_folder(folder):
    """Persist `folder` as the most-recently-used open/save location."""
    if not folder:
        return
    path = _path()
    if path is None:
        return
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'w', encoding='utf-8') as f:
            f.write(folder)
    except (OSError, IOError):
        pass
